INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11301, 'Ezra 5:5', 'Ezra', 5, 5, '&nbsp;خو په يهودى مشرانو باندې د خُدائ پاک نظر وو او د فارس آفسرانو دا فېصله وکړه چې تر هغې پورې به يو کار هم نۀ کوى چې ترڅو يې داريوس بادشاه له خط نۀ وى لېږلے او جواب يې نۀ وى راغلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11302, 'Ezra 5:6', 'Ezra', 5, 6, '&nbsp;هغوئ داريوس بادشاه له دا خبر ورولېږلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11303, 'Ezra 5:7', 'Ezra', 5, 7, '&nbsp;”داريوس بادشاه ته ډېر ډېر سلامونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11304, 'Ezra 5:8', 'Ezra', 5, 8, '&nbsp;بادشاه سلامت، تا ته دې پته وى چې مونږ د يهوداه صُوبې ته ورغلو او ومو ليدل چې د عظيم خُدائ پاک کور د لويو کاڼو او په دېوالونو کښې د لرګو د ستنو سره بيا جوړيږى. کار د ډېر احتياط سره کولے شى او ډېر ښۀ روان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11305, 'Ezra 5:9', 'Ezra', 5, 9, '&nbsp;مونږ بيا د خلقو د مشرانو نه تپوس وکړو چې مونږ ته ووائى چې هغوئ له دا اختيار چا ورکړ‌ے دے چې د خُدائ پاک کور بيا جوړ کړى او سر ته يې ورسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11306, 'Ezra 5:10', 'Ezra', 5, 10, '&nbsp;مونږ د هغوئ د نومونو تپوس هم وکړو نو چې داسې مونږ تا خبر کړُو چې د دې کار مشران څوک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11307, 'Ezra 5:11', 'Ezra', 5, 11, '&nbsp;هغوئ مونږ له جواب راکړو چې مونږ د آسمان او زمکې د خُدائ پاک خِدمتګار يُو او مونږ هغه کور بيا جوړوُو کوم چې په اصل کښې ډېره موده مخکښې د بنى اِسرائيلو يو تکړه بادشاه جوړ کړے وو او سر ته يې رسولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11308, 'Ezra 5:12', 'Ezra', 5, 12, '&nbsp;خو زمونږ پلار نيکۀ د آسمان خُدائ پاک غصه کړو نو په دې وجه هغوئ يې د بابل بادشاه نبوکدنضر ته پرېښودل، چا چې دا کور وران کړو او خلق يې بابل ته جلاوطن کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11309, 'Ezra 5:13', 'Ezra', 5, 13, '&nbsp;خو بيا چې کله خورس بادشاه د بابل بادشاه شو نو د هغۀ د بادشاهۍ په وړومبى کال، خورس دا حُکم وکړو چې د خُدائ پاک کور دې بيا جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11310, 'Ezra 5:14', 'Ezra', 5, 14, '&nbsp;هغۀ د خُدائ پاک په کور کښې د سرو زرو او سپينو زرو لوښى بيا کېښودل کوم چې نبوکدنضر د خُدائ پاک د کور نه اوړى وُو چې هغه کور په يروشلم کښې وو او په بابل کښې يې په عبادتخانه کښې اېښى وُو. خورس بادشاه دا لوښى د يو سړى په حواله کړل چې د هغۀ نوم شيسبضر وو، کوم چې هغۀ د يهوداه حکمران مقرر کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11311, 'Ezra 5:15', 'Ezra', 5, 15, '&nbsp;بادشاه هغۀ ته ووئيل چې دا يوسى او په يروشلم کښې يې د خُدائ پاک کور ته واپس کړى او هغه کور په هغه ځائ باندې بيا جوړ کړى چې چرته مخکښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11312, 'Ezra 5:16', 'Ezra', 5, 16, '&nbsp;نو شيسبضر راغلو او د دې بنياد يې کېښودو، د دې جوړېدل د هغه وخت نه واخله تر ننه پورې جارى وُو، خو د خُدائ پاک کور تر اوسه پورې مکمل شوے نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11313, 'Ezra 5:17', 'Ezra', 5, 17, '&nbsp;نو بادشاه سلامت، کۀ ستا خوښه وى نو د بابل شاهى تاريخ دې ولټولے شى نو دا به معلوم شى چې خورس په يروشلم کښې د خُدائ پاک د کور د بيا جوړولو حُکم ورکړے وو او کۀ نه، او بيا مونږ خبر کړه چې په دې معامله کښې ستا خوښه څۀ ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11314, 'Ezra 6:1', 'Ezra', 6, 1, '&nbsp;نو داريوس بادشاه حُکم جارى کړو چې د بابل هغه شاهى تاريخ دې ولټولے شى کوم چې په خزانه کښې ساتلے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11315, 'Ezra 6:2', 'Ezra', 6, 2, '&nbsp;خو د مادى صُوبې په اکبتانا ښار کښې يو طومار پېدا شو، چې دا ليکل په کښې شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11316, 'Ezra 6:3', 'Ezra', 6, 3, '&nbsp;”د خپلې بادشاهۍ په وړومبى کال خورس بادشاه حُکم وکړو چې په يروشلم کښې دې د خُدائ پاک کور بيا جوړ کړے شى چې هغه يو داسې ځائ وى چرته به چې قربانۍ کيږى او نذرانې به سوزولے شى. د خُدائ پاک کور به تقريباً دېرش ګزه اوچت او دېرش ګزه پلن جوړولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11317, 'Ezra 6:4', 'Ezra', 6, 4, '&nbsp;دېوالونه به داسې جوړولے شى چې درې ردې د لويو کاڼو وى او په يوه رَده کښې د لرګى تختې لګولے شوى وى. دا ټوله خرچه به شاهى خزانه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11318, 'Ezra 6:5', 'Ezra', 6, 5, '&nbsp;نبوکدنضر بادشاه چې په يروشلم کښې د خُدائ پاک د کور نه کوم د سرو زرو او سپينو زرو لوښى بابل ته اوړى وُو نو هغه به هم د خُدائ پاک کور يعنې خپل صحيح ځائ ته راواپس کولے شى کوم چې په يروشلم کښې دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11319, 'Ezra 6:6', 'Ezra', 6, 6, '&nbsp;نو بيا داريوس بادشاه دا جواب ورولېږلو، ”دا د نمرپرېواتۀ طرف ته فرات حکمران تتنى، شتربوزنى او د نمرپرېواتۀ طرف ته فرات ستا آفسرانو ته دے، چې تاسو به د خُدائ پاک د کور سره کار نۀ ساتئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11320, 'Ezra 6:7', 'Ezra', 6, 7, '&nbsp;او د دې په جوړېدو کښې کار مۀ ساتئ. د يهوداه حکمران او يهودى مشران پرېږدئ چې هغوئ د خُدائ پاک کور هلته جوړ کړى چرته چې مخکښې ولاړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11321, 'Ezra 6:8', 'Ezra', 6, 8, '&nbsp;او دې سره زۀ تاسو له حُکم درکوم چې د يهوداه د مشرانو مدد وکړئ چې دا بيا جوړ کړى. هغوئ له به د پوره خرچې دپاره د شاهى خزانې پېسې ورکولے شى چې د نمرپرېواتۀ طرف ته د فرات د محصُول نه اخستے شى، د دې دپاره چې کار ايسار نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11322, 'Ezra 6:9', 'Ezra', 6, 9, '&nbsp;بغېر د څۀ کمى نه، هره ورځ تاسو به په يروشلم کښې اِمامانو له هغه هر څۀ ورکوئ چې هغوئ ته د څۀ ضرورت وى، چې هغه سخى، ګډې، يا ګډُورى وى، چې د آسمان خُدائ پاک ته د قربانۍ په توګه سوزولے شى، يا چې هغه غنم، مالګه، مے، يا د زيتُونو تېل وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11323, 'Ezra 6:10', 'Ezra', 6, 10, '&nbsp;نو چې داسې هغوئ هغه قربانۍ پېش کړى په کومو باندې چې د آسمان خُدائ پاک رضا کيږى او زما او زما د زامنو دپاره د هغۀ نه برکت غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11324, 'Ezra 6:11', 'Ezra', 6, 11, '&nbsp;زۀ بل دا حُکم کوم کۀ څوک هم دا حُکم ونۀ منى، نو د هغۀ کور نه به د لرګى تير راوويستلے شى، د هغې يو سر دې تېرۀ کړے شى او په هغې دې ووژلے شى. او د هغۀ کور دې د ډېران يو ډېرے جوړ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11325, 'Ezra 6:12', 'Ezra', 6, 12, '&nbsp;هغه خُدائ پاک چا چې يروشلم د دې دپاره خوښ کړے دے چې هلته به د هغۀ عبادت کيږى نو کۀ کوم بادشاه يا قوم د دې حُکم نه اِنکار وکړى يا د دې کور د تباه کولو کوشش کوى نو خُدائ پاک دې ورله شکست ورکړى. ما داريوس دا حُکم کړے دے او دا حُکم دې پوره ومنلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11326, 'Ezra 6:13', 'Ezra', 6, 13, '&nbsp;بيا تتنى حکمران، شتربوزنى او د هغوئ آفسرانو هم هغه شان وکړل چې څنګه داريوس بادشاه حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11327, 'Ezra 6:14', 'Ezra', 6, 14, '&nbsp;يهودى مشرانو د خُدائ پاک د کور عمارت په ښۀ طريقه جوړولو، چې د هغوئ حوصله افزائى حجى او زکرياه پېغمبرانو کوله. هغوئ د خُدائ پاک کور هم هغه شان سر ته ورسولو لکه څنګه چې د بنى اِسرائيلو خُدائ پاک حُکم کړے وو او خورس، داريوس او د فارس بادشاه ارتخششتا فرمان جارى کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11328, 'Ezra 6:15', 'Ezra', 6, 15, '&nbsp;هغوئ د خُدائ پاک کور د داريوس بادشاه د بادشاهۍ په شپږم کال کښې د ادر مياشتې په درېمه ورځ سر ته ورسولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11329, 'Ezra 6:16', 'Ezra', 6, 16, '&nbsp;بيا بنى اِسرائيلو، اِمامانو او ليويانو او هغه نورو ټولو خلقو په خوشحالۍ سره د خُدائ پاک کور وقف کړو کوم چې د جلاوطنۍ نه راواپس شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11330, 'Ezra 6:17', 'Ezra', 6, 17, '&nbsp;د وقف کولو دپاره هغوئ سل غوَيى، دوه سوه ګډان او څلور سوه ګډُورى د قربانۍ په توګه پېش کړل او دولس چېلى يې د ګناه د نذرانې په توګه پېش کړل چې د بنى اِسرائيلو د هرې يوې قبيلې دپاره يو يو وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11331, 'Ezra 6:18', 'Ezra', 6, 18, '&nbsp;هغوئ په يروشلم کښې د خُدائ پاک د کور د خِدمت دپاره اِمامان او ليويان د هغه اصُولو په مطابق منتخب کړل کوم چې د موسىٰ په کِتاب کښې ليکلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11332, 'Ezra 6:19', 'Ezra', 6, 19, '&nbsp;کوم خلق چې د جلاوطنۍ نه راواپس شوى وُو نو هغوئ په ورپسې کال د اولې مياشتې په څوارلسمه ورځ د فسحې اختر وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11333, 'Ezra 6:20', 'Ezra', 6, 20, '&nbsp;ټولو اِمامانو او ليويانو خپل ځانونه پاک کړى وُو او د پاکېدو رسم يې ادا کړے وو. ليويانو د فسحې د اختر د قربانۍ دپاره د ټولو راواپس شوو خلقو، د اِمامانو او د خپلو ځانونو دپاره څاروى حلال کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11334, 'Ezra 6:21', 'Ezra', 6, 21, '&nbsp;دا قربانۍ هغه ټولو بنى اِسرائيلو وخوړلې چې څوک د جلاوطنۍ نه راواپس شوى وُو او ورسره هغه خلقو هم وخوړلې چا چې د غېرو قومونو غلط رسمونه پرېښى وُو د دې دپاره چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11335, 'Ezra 6:22', 'Ezra', 6, 22, '&nbsp;هغوئ د خوشحالۍ سره اووۀ ورځې د پتيرې روټۍ اختر وکړو. هغوئ ډېر خوشحاله وُو ځکه چې مالِک خُدائ د اسور بادشاه په هغوئ باندې مهربان کړے وو، نو په دې وجه هغۀ د هغوئ په کار کښې مدد وکړو چې د بنى اِسرائيلو د خُدائ پاک کور جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11336, 'Ezra 7:1', 'Ezra', 7, 1, '&nbsp;ډېره موده پس، کله چې ارتخششتا د فارس بادشاه وو، نو يو سړے وو چې نوم يې عزرا وو. هغۀ خپله شجره نسب مشر اِمام هارون ته ورسوله، چې داسې ده: عزرا د شراياه زوئ وو چې هغه زوئ د عزرياه، زوئ د خِلقياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11337, 'Ezra 7:2', 'Ezra', 7, 2, '&nbsp;زوئ د سلوم، زوئ د صدوق، زوئ د اخيطوب،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11338, 'Ezra 7:3', 'Ezra', 7, 3, '&nbsp;زوئ د امرياه، زوئ د عزرياه، زوئ د مرايوت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11339, 'Ezra 7:4', 'Ezra', 7, 4, '&nbsp;زوئ د زرخياه، زوئ د عُزى، زوئ د بُقى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11340, 'Ezra 7:5', 'Ezra', 7, 5, '&nbsp;زوئ د ابيسوع، زوئ د فينحاس، زوئ د اِلى‌عزر او زوئ د هارون څوک چې مشر اِمام وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11341, 'Ezra 7:10', 'Ezra', 7, 10, '&nbsp;عزرا خپل ژوند دې ته وقف کړے وو چې د مالِک خُدائ په قانون باندې پوهه شى، په هغې عمل وکړى او د دې ټول قانون او اصُول بنى اِسرائيلو ته وښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11342, 'Ezra 7:11', 'Ezra', 7, 11, '&nbsp;ارتخششتا عزرا اِمام او عالِم له دا کاغذ ورکړو، چې هغۀ د هغه قانون او حُکمونه پوره پوهه لرله کوم چې مالِک خُدائ بنى اِسرائيلو ته ورکړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11343, 'Ezra 7:12', 'Ezra', 7, 12, '&nbsp;”د ارتخششتا بادشاه د طرف نه، عزرا اِمام ته، چې هغه د آسمان د خُدائ پاک د قانون عالِم دے، ډېر سلامونه. او اوس،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11344, 'Ezra 7:13', 'Ezra', 7, 13, '&nbsp;زۀ دا حُکم کوم چې زما په ټول سلطنت کښې چې کوم بنى اِسرائيليان، اِمامان او ليويان چې د هغوئ زړۀ غواړى چې تا سره يروشلم ته لاړ شى نو لاړ دې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11345, 'Ezra 7:14', 'Ezra', 7, 14, '&nbsp;زۀ، تا زما د خپلو اووۀ مشيرانو سره لېږم چې په يروشلم او يهوداه کښې حالات معلوم کړئ چې دا پته ولګى چې ستا د خُدائ پاک په قانون باندې څومره ښۀ عمل کيږى، هغه قانون چې تا سره موجود دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11346, 'Ezra 7:15', 'Ezra', 7, 15, '&nbsp;تاسو به د ځان سره د سرو زرو او سپينو زرو هغه نذرانې يوسئ د کومو چې زۀ او زما مشيران د بنى اِسرائيلو خُدائ پاک له د ورکولو خواهش لرو، هغه خُدائ پاک چې د هغۀ کور په يروشلم کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11347, 'Ezra 7:16', 'Ezra', 7, 16, '&nbsp;تاسو به هغه ټول سرۀ زر او سپين زر هم د ځان سره اوړئ کوم چې تاسو د بابل په ټوله صُوبه کښې راغونډ کړئ او هغه نذرانې به هم اوړئ کومې چې بنى اِسرائيليان او د هغوئ اِمامان په يروشلم کښې د خپل خُدائ پاک کور دپاره ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11348, 'Ezra 7:17', 'Ezra', 7, 17, '&nbsp;تاسو به دا پېسې په احتياط سره خرچ کوئ او غوَيى، ګډان او ګډُورى، غله او مے په بيعه واخلئ او په يروشلم کښې يې د خُدائ پاک د کور په قربان‌ګاه باندې پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11349, 'Ezra 7:18', 'Ezra', 7, 18, '&nbsp;کوم سرۀ زر او سپين زر چې پاتې شى نو چې ستا او ستا د خلقو هر څنګه خوښه وى نو هغه شان يې استعمالولے شئ، خو د خُدائ پاک د رضا په مطابق.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11350, 'Ezra 7:19', 'Ezra', 7, 19, '&nbsp;تاسو به په يروشلم کښې خُدائ پاک ته هغه ټول لوښى پېش کوئ کوم چې د خُدائ پاک د کور د خِدمت د استعمال دپاره درکړے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11351, 'Ezra 7:20', 'Ezra', 7, 20, '&nbsp;او تاسو ته چې د خُدائ پاک د کور دپاره د بل هر څيز ضرورت وى، نو تاسو هغه د شاهى خزانې نه اخستلے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11352, 'Ezra 7:21', 'Ezra', 7, 21, '&nbsp;زۀ د فرات سيند د نمرپرېواتۀ صُوبې د خزانې ټولو آفسرانو له حُکم ورکوم چې هغوئ د عالِم عزرا اِمام دپاره د هغه هر څۀ ښۀ بندوبست وکړى چې هغه يې غواړى، عزرا د آسمان د خُدائ پاک په قانون کښې عالِم دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11353, 'Ezra 7:22', 'Ezra', 7, 22, '&nbsp;د دې حد به د درې زره او څلور سوو کلو سپينو زرو، د لسو زرو کلو غنمو، دوه زره ليټره مے او دوه زره ليټره د زيتُونو تېلو پورې وى او چې داسې څومره د مالګې ضرورت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11354, 'Ezra 7:23', 'Ezra', 7, 23, '&nbsp;تاسو به خامخا د هغه هر څۀ په بندوبست کولو کښې د احتياط نه کار اخلئ چې د آسمان خُدائ پاک يې د خپل کور دپاره غوښتنه کوى او پام کوئ چې هغه ما ته او هغه کسانو ته هيڅکله غصه نۀ شى کوم چې زما نه پس بادشاهى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11355, 'Ezra 7:24', 'Ezra', 7, 24, '&nbsp;تاسو ته د دې اجازت نشته چې د اِمامانو، ليويانو، موسيقارانو، څوکيدارانو، کاريګرو، يا د بل هر هغه چا نه محصُول، جزيه او پېسې واخلئ چې د چا تعلق د خُدائ پاک د دې کور سره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11356, 'Ezra 7:25', 'Ezra', 7, 25, '&nbsp;عزرا، تۀ به د هغه حِکمت نه کار اخلې کوم چې ستا خُدائ پاک درکړے دے، تۀ به اِنتظام کوونکى او قاضيان مقرروې چې په هغه ټولو خلقو باندې حکومت کوى چې د فرات سيند نمرپرېواتۀ طرف ته د خُدائ پاک د قانون لاندې ژوند تېروى. تۀ به هغه هر چا ته دا قانون ښائې چې څوک ورباندې نۀ پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11357, 'Ezra 7:26', 'Ezra', 7, 26, '&nbsp;کۀ هر څوک هم ستا د خُدائ پاک د قانون يا د بادشاه د قانون نافرمانى کوى، نو هغۀ له به هم په هغه وخت سزا ورکولے شى، چې وژلے به شى، يا به جلاوطن کړے شى، يا به د هغۀ نه جائيداد ضبط کولے شى، يا به قېد کولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11358, 'Ezra 7:27', 'Ezra', 7, 27, '&nbsp;عزرا وفرمائيل، ”د مالِک خُدائ زمونږ د پلار نيکۀ د خُدائ پاک ثناء صِفت دې وى. هغۀ بادشاه دې ته راضى کړے دے چې په دې طريقه باندې په يروشلم کښې د مالِک خُدائ د کور درناوى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11359, 'Ezra 7:28', 'Ezra', 7, 28, '&nbsp;د خُدائ پاک په فضل سره په ما باندې بادشاه، د هغۀ مشيران او د هغۀ ټول طاقتور آفسران مهربان شوى دى، مالِک خُدائ زما خُدائ پاک ما له حوصله راکړې ده او زۀ د دې قابل شوے يم چې د بنى اِسرائيلو د ډلو ډېر مشران دې ته جوړ کړم چې زما سره راواپس شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11360, 'Ezra 8:1', 'Ezra', 8, 1, '&nbsp;دا د هغه ډلو د مشرانو تفصيل دے کوم چې په بابل کښې جلاوطن وُو او چې هغوئ د عزرا سره په هغه وخت کښې يروشلم ته راواپس شول چې په کوم وخت کښې ارتخششتا بادشاه وُو:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11361, 'Ezra 8:15', 'Ezra', 8, 15, '&nbsp;ما د هغه نِهر سره ټوله ډله راغونډه کړه کوم چې د اهاوا ښار ته بهيږى او مونږ هلته درې ورځې خېمې لګولې وې. ما وليدل چې هلته په ډله کښې اِمامان وُو، خو ليويان نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11362, 'Ezra 8:16', 'Ezra', 8, 16, '&nbsp;نو ما دا نهۀ مشران راوغوښتل: اِلى‌عزر، ارى‌ايل، سمعياه، الناتن، يريب، الناتن، ناتن، زکرياه او مسلام او دوه عالمان يويريب او الناتن مې هم راوغوښتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11363, 'Ezra 8:17', 'Ezra', 8, 17, '&nbsp;ما هغوئ په کسيفيا کښې د قبيلې مشر عدو ته ولېږل، چې هغۀ او د هغۀ د قبيلې نه د خُدائ پاک د کور دپاره کاريګر وغواړى او مونږ له داسې خلق راولېږى چې د خُدائ پاک په کور کښې خِدمت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11364, 'Ezra 8:18', 'Ezra', 8, 18, '&nbsp;د خُدائ پاک په فضل سره هغوئ مونږ له يو تکړه سړے سربياه راولېږلو، چې دے د محلى د قبيلې ليوے وو او اتلس زامن او وروڼه د هغۀ سره راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11365, 'Ezra 8:19', 'Ezra', 8, 19, '&nbsp;هغوئ د مرارى قبيلې حسبياه او يشعياه هم د هغوئ د شلو خپلوانو سره راولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11366, 'Ezra 8:20', 'Ezra', 8, 20, '&nbsp;د دې نه علاوه د خُدائ پاک د کور دوه سوه او شل داسې خِدمتګاران هم وُو چې داؤد بادشاه او د هغۀ آفسرانو د هغوئ پلار نيکۀ د دې دپاره مقرر کړى وُو چې د ليويانو مدد کوى. او د هغوئ ټولو نومونه ليکلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11367, 'Ezra 8:21', 'Ezra', 8, 21, '&nbsp;هلته د اهاوا نِهر سره ما ټولو له دا حُکم ورکړو چې روژه ونيسئ او د خپل خُدائ پاک په وړاندې خپل ځانونه عاجزان کړئ او هغۀ ته سوال وکړئ چې په سفر کښې زمونږ مدد وکړى او زمونږ، زمونږ د بچو او زمونږ د مال دولت حِفاظت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11368, 'Ezra 8:22', 'Ezra', 8, 22, '&nbsp;زۀ په دې باندې شرمېدلم چې د بادشاه نه مې يو لښکر او په آسونو سوارۀ فوجيان غوښتى وے چې زمونږ د سفر په دوران کښې د دشمنانو نه زمونږ حِفاظت وکړى، ځکه چې ما هغۀ ته وئيلى وُو چې زمونږ خُدائ پاک هغه هر چا له برکت ورکوى چې څوک ورباندې ايمان لرى، خو هر څوک چې د هغۀ نه واوړى نو د هغوئ نه خفه کيږى او سزا ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11369, 'Ezra 8:23', 'Ezra', 8, 23, '&nbsp;نو مونږ روژه ونيوله او خُدائ پاک ته مو سوال وکړو چې زمونږ حِفاظت وکړى او هغۀ زمونږ سوال قبول کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11370, 'Ezra 8:24', 'Ezra', 8, 24, '&nbsp;د مشرانو اِمامانو نه ما سربياه، حسبياه او لس نور کسان خوښ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11371, 'Ezra 8:25', 'Ezra', 8, 25, '&nbsp;بيا ما هغه سپين زر، سرۀ زر او لوښى وتلل کوم چې بادشاه، د هغۀ مشيرانو او د هغۀ آفسرانو او بنى اِسرائيلو د دې دپاره راکړى وُو چې د خُدائ پاک په کور کښې استعمال شى او ما دا اِمامانو له ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11372, 'Ezra 8:28', 'Ezra', 8, 28, '&nbsp;ما اِمامانو ته ووئيل، ”تاسو مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک ته وقف او مقدس شوى يئ او داسې هغه ټول سپين زر، سرۀ زر او لوښى هم ستاسو په شان مقدس دى کوم چې هغۀ ته د رضاکارانه نذرانو په توګه راوړلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11373, 'Ezra 8:29', 'Ezra', 8, 29, '&nbsp;د مالِک خُدائ کور ته تر رسېدو پورې د دې ښۀ حِفاظت وکړئ. هلته د اِمامانو په کوټه کښې دا وتلئ او د مشرانو اِمامانو او د ليويانو او په يروشلم کښې د بنى اِسرائيلو مشرانو ته يې حواله کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11374, 'Ezra 8:30', 'Ezra', 8, 30, '&nbsp;نو اِمامانو او ليويانو د هغه سپينو زرو، سرو زرو او د لوښو ذمه وارى واخستله چې په يروشلم کښې يې د مالِک خُدائ کور ته يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11375, 'Ezra 8:31', 'Ezra', 8, 31, '&nbsp;دا د اولې مياشتې دولسمه ورځ وه چې مونږ يروشلم ته د تلو دپاره د اهاوا نِهر نه روان شُو. زمونږ خُدائ پاک مل وو او چې مونږ سفر کولو نو مونږ يې د دشمن د حملو نه او د ډاکوانو نه بچ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11376, 'Ezra 8:32', 'Ezra', 8, 32, '&nbsp;کله چې مونږ يروشلم ته ورسېدو، نو مونږ درې ورځې آرام وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11377, 'Ezra 8:33', 'Ezra', 8, 33, '&nbsp;او بيا په څلورمه ورځ مونږ د خُدائ پاک کور ته لاړو او هغه سپين زر، سرۀ زر او لوښى مو وتلل او د اورِياه زوئ مريموت اِمام ته مو حواله کړل. د هغۀ سره اِلى‌عزر، د فينحاس زوئ او دوه ليويان، د يشوَع زوئ يوزبد او د بِنوئى زوئ نوعيدياه هم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11378, 'Ezra 8:34', 'Ezra', 8, 34, '&nbsp;هر يو څيز وشمېرلے شو او تللے شو او په هغه وخت پوره حِساب کِتاب وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11379, 'Ezra 8:35', 'Ezra', 8, 35, '&nbsp;بيا هغه ټولو خلقو نذرانې راوړې کوم چې د جلاوطنۍ نه راغلى وُو چې د بنى اِسرائيلو خُدائ پاک ته د قربانۍ په توګه وسوزولے شى. هغوئ د ټولو بنى اِسرائيلو دپاره دولس غوَيى، څلور کم سل ګډان، اووۀ اويا ګډُورى پېش کړل، هغوئ دولس چېلى هم پېش کړل چې خپل ځانونه د ګناه نه پاک کړى. دا ټول ځناور مالِک خُدائ ته د قربانۍ په توګه وسوزولے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11380, 'Ezra 8:36', 'Ezra', 8, 36, '&nbsp;هغوئ هغه ليکلے شوے فرمان هم راوخستلو کوم چې بادشاه ورکړے وو او هغه يې حکمرانانو او د نمرپرېواتۀ طرف فرات ته د صُوبې آفسرانو له ورکړو، چې هغوئ بيا د هغه خلقو سره او د خُدائ پاک د کور سره مدد وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11381, 'Ezra 9:1', 'Ezra', 9, 1, '&nbsp;کله چې دا هر څۀ وشول نو د بنى اِسرائيلو څۀ مشران راغلل او ما ته يې ووئيل چې خلقو، اِمامانو او ليويانو خپل ځانونه د ګاونډى مُلکونو يعنې عمون، موآب، مِصر، کنعان، حِتى، فرزى، يبوس او امورى مُلک د خلقو نه جدا نۀ ساتل. دوئ هم هغه حرام کارونه کول چې کوم هغه خلقو کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11382, 'Ezra 9:2', 'Ezra', 9, 2, '&nbsp;يهوديانو سړو د پردى مُلک ښځو سره ودونه کول، نو په دې وجه د خُدائ پاک مقدس خلق پليت شول. د افسوس خبره دا ده چې مشران او آفسران په دې بدعملۍ کښې د هر چا نه وړاندې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11383, 'Ezra 9:3', 'Ezra', 9, 3, '&nbsp;کله چې زۀ د دې نه خبر شوم نو ما د خفګان نه خپل قميص او چُوغه وشلوله، د سر او د ږيرې وېښتۀ مې وويستل او غم زپلے کښېناستم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11384, 'Ezra 9:4', 'Ezra', 9, 4, '&nbsp;نو څوک چې د بنى اِسرائيلو د خُدائ پاک د کلام په وجه يرېدلى وُو ځکه چې هغوئ د جلاوطنۍ نه راواپس خلقو د نافرمانۍ نه خبر شول هغوئ ټول راغلل او زما سره کښېناستل. او زۀ هلته د ماښام د قربانۍ د وخت پورې سخت خفه ناست وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11385, 'Ezra 9:5', 'Ezra', 9, 5, '&nbsp;کله چې د ماښام د نذرانې وخت راغلو نو زۀ چې د خفګان نه چرته ناست وم د هغه ځائ نه پاڅېدم، چې تر اوسه پورې مې شلېدلے قميص او چُوغه اغوستې وه سجده مې وکړه او بيا مالِک خُدائ خپل خُدائ پاک ته مې لاسونه پورته کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11386, 'Ezra 9:6', 'Ezra', 9, 6, '&nbsp;ما وئيل، ”خُدايه پاکه، ما له په دې باندې ډېر سخت شرم راځى چې ستا په حضور کښې خپل لاسونه اوچت کړم. زمونږ ګناهونه زمونږ د سرونو نه پاس اوړېدلى دى او زمونږ ګناهونه تر آسمانه پورې رسېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11387, 'Ezra 9:7', 'Ezra', 9, 7, '&nbsp;زمونږ د پلار نيکۀ د وخت نه واخله تر اوسه پورې مونږ يعنې ستا خلقو لوئې ګناهونه کړې دى. زمونږ د خپلې ګناه په وجه مونږ، زمونږ بادشاهان او زمونږ اِمامان د پردى مُلک بادشاهانو له په لاس ورغلى يُو او مونږ وژلے شُو، غلا رانه کيږى او د قېديانو په توګه بوتلے شُو. زمونږ ډېره بې‌عزتى شوې ده لکه څنګه چې تر اوسه پورې بې‌عزته يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11388, 'Ezra 9:8', 'Ezra', 9, 8, '&nbsp;خو اے مالِکه خُدايه، زمونږ خُدايه پاکه، تۀ د لږ وخت دپاره په مونږ مِهربانه يې چې زمونږ څۀ کسان دې ژوندى پرېښى دى چې د غلامۍ نه وتښتى او په دې مقدس ځائ کښې په حِفاظت سره اوسيږى. تا مونږ د غلامۍ نه آزاد کړى يُو او يو نوے ژوند دې راکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11389, 'Ezra 9:9', 'Ezra', 9, 9, '&nbsp;مونږ غلامان وُو، خو تا مونږ په غلامۍ کښې پرې نۀ ښودو. تا د فارس بادشاهان مونږ سره ښۀ کړل او دا اجازت دې راکړو چې خپل ژوند تېروو او ستا هغه کور بيا جوړ کړُو، کوم چې تباه شوے وو او دې ته دې هم پرېښودو چې په يهوداه او يروشلم کښې مونږ ته حِفاظت مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11390, 'Ezra 9:10', 'Ezra', 9, 10, '&nbsp;خو اے خُدايه پاکه، نو مونږ په دې کښې څۀ ووايو؟ مونږ ستا د حُکمونو بيا نافرمانى کړې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11391, 'Ezra 9:11', 'Ezra', 9, 11, '&nbsp;هغه حُکمونه کوم چې تا مونږ له د خپلو خِدمت کوونکو پېغمبرانو په ذريعه راکړى وُو. هغوئ مونږ ته ووئيل چې مونږ د کوم مُلک قبضه کولو له روان يُو هغه مُلک د هغه خلقو د بد عملى په وجه ناپاک وو کوم چې په کښې اوسېدل او هغوئ دا د يو سر نه تر بله سر پورې د بې‌شرمۍ او حرام کارونو نه ډک کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11392, 'Ezra 9:12', 'Ezra', 9, 12, '&nbsp;هغوئ مونږ ته ووئيل چې مونږ دې هيڅکله د هغه خلقو سره ودونه ونۀ کړُو او نۀ د هغوئ سره د ښۀ کېدو او کاميابېدو دپاره مدد وکړُو دا د دې دپاره چې هغه څيزونه مونږ ته مِلاو شى چې په هغه مُلک کښې پېدا کيږى او چې دا مُلک به زمونږ اولاد ته په ميراث کښې مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11393, 'Ezra 9:13', 'Ezra', 9, 13, '&nbsp;خو اوس چې مونږ ته زمونږ د ګناه او بدۍ په وجه چې کومه سزا مِلاو شوه، مونږ ته دا پته ده زمونږ خُدايه پاکه، چې تا مونږ له د هغې نه کمه سزا راکړې ده چې د څومره مونږ حقدار وُو او زمونږ څۀ خلق دې ژوندى پرېښى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11394, 'Ezra 9:14', 'Ezra', 9, 14, '&nbsp;نو بيا مونږ ستا حُکمونه څنګه مات کړُو او هغه حرام کاره خلقو سره ودونه وکړُو؟ کۀ مونږ داسې وکړُو نو تۀ به دومره غصه شې چې تباه به مو کړې او يو کس به هم ژوندے پرې نۀ ږدې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11395, 'Ezra 9:15', 'Ezra', 9, 15, '&nbsp;مالِکه خُدايه، د بنى اِسرائيلو خُدايه پاکه، تۀ صادق يې، خو تا مونږ پرېښودو چې ژوندى پاتې شُو. مونږ په ګناه کښې ستا په وړاندې ولاړ يُو، خو د دې ګناه په وجه زمونږ يو کس هم دا حق نۀ لرى چې ستا حضور ته راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11396, 'Ezra 10:1', 'Ezra', 10, 1, '&nbsp;کله چې عزرا د خُدائ پاک د کور په مخکښې پړمخې پرېوتو، چې هغۀ ژړل او د ګناهونو اِقرار يې کولو، نو د بنى اِسرائيلو يوه لويه ډله د هغۀ نه راتاو شوه چې په کښې سړى، ښځې او ماشومان شامل وُو او بد بد يې ژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11397, 'Ezra 10:2', 'Ezra', 10, 2, '&nbsp;د عيلام قبيلې د يحى‌ايل زوئ سکانياه عزرا ته ووئيل، ”د غېرو قومونو د ښځو سره ودونه کولو په وجه مونږ د خُدائ پاک سره بې‌وفائى کړې ده، خو بيا هم د اِسرائيل دپاره اُميد شته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11398, 'Ezra 10:3', 'Ezra', 10, 3, '&nbsp;نو چې اوس مونږ د خپل خُدائ پاک سره دا لوظ وکړُو چې مونږ به دا ښځې طلاقې کړُو او سره د ماشومانو به يې وشړُو. مونږ به هم هغه شان وکړُو چې څنګه تۀ او هغه نور کسان مشوره راکړئ چې کوم د خُدائ پاک د حُکمونو درناوے کوى. چې د خُدائ پاک قانون څۀ مطالبه کوى نو مونږ به هم هغه شان کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11399, 'Ezra 10:4', 'Ezra', 10, 4, '&nbsp;اوس پاڅه، دا خبره ستا په لاس کښې ده. مونږ به ستا ملګرتيا کوُو، نو تکړه شه او دا کار وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11400, 'Ezra 10:5', 'Ezra', 10, 5, '&nbsp;عزرا پاڅېدو او د اِمامانو د مشرانو، ليويانو او د ټولو بنى اِسرائيلو نه يې دا قسم واخستو چې هغوئ به د سکانياه په مشوره باندې عمل کوى. نو داسې هغوئ قسم وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');